#include "combat/Simulation.hpp"
#include <iostream>
using namespace dw;
int main(){Simulation s(8,1,{},MissionTheme::Canyon,true,false,WitnessAccount::Rourke,4);s.jumpDebug(10);s.godMode=true;s.debugScenario=true;auto it=std::find_if(s.enemies.begin(),s.enemies.end(),[](const auto&e){return e.monster==monsterId(29,2);});auto e=*it;for(int n=0;n<24;++n){auto p=add(e.position,rotateY({0,0,7},float(n)*Pi/12));p.y=.85f;if(s.arena.roomAt(p)!=10||s.arena.blocked(p,.48f)||!s.arena.sight(p,e.position))continue;if(std::any_of(s.enemies.begin(),s.enemies.end(),[&](const auto&o){return distance(p,o.position)<3;}))continue;s.player.position=p;break;}auto bounds=s.arena.rooms[10].bounds;auto p=s.player.position;const auto axis=[&](float v,float lo,float hi){return std::clamp(lo+2+std::round((v-lo-2)/4)*4,lo+.65f,hi-.65f);};auto snapped=Vector3{axis(p.x,bounds.min.x,bounds.max.x),.85f,axis(p.z,bounds.min.z,bounds.max.z)};std::cout<<"enemy="<<e.position.x<<","<<e.position.z<<" target="<<p.x<<","<<p.z<<" snapped="<<snapped.x<<","<<snapped.z<<" targetBlocked="<<s.arena.blocked(p,e.radius)<<" snappedBlocked="<<s.arena.blocked(snapped,e.radius)<<"\n";for(int n=0;n<500;++n)s.step({});std::cout<<"hops="<<s.findEnemy(e.id)->targetHop->hops<<" patches="<<s.findEnemy(e.id)->eggy->creepPatches<<"\n";}
